SELECT ?node ?label ?p ?s ?id WHERE {
  ?node ref:hasExternalReference ?s .
  OPTIONAL { ?node rdfs:label ?label }
  OPTIONAL { ?p ref:hasTimeseriesId ?id ; ref:hasExternalReference ?s }
  FILTER(CONTAINS(str(?node), "Perimeter_bot_ZN_2") || (CONTAINS(str(?s),"Perimeter_bot_ZN_2")))
}

SELECT ?point ?class ?reflabel ?id WHERE {
  ?point ref:hasExternalReference/ref:hasTimeseriesId ?id .
  ?point a ?class .
  OPTIONAL { ?point rdfs:label ?reflabel }
  FILTER(CONTAINS(str(?point), "Perimeter_bot_ZN_2") || CONTAINS(str(?class),"Lighting") || CONTAINS(str(?class),"Occupancy"))
}

SELECT ?zone ?zlabel WHERE {
  ?zone a brick:Zone .
  OPTIONAL { ?zone rdfs:label ?zlabel }
}

SELECT ?zone ?sensor ?sclass WHERE {
  ?zone a brick:Zone .
  FILTER(CONTAINS(str(?zone), "ZN_2") || CONTAINS(str(?zone), "Perimeter") || CONTAINS(str(?zone), "bot"))
  ?sensor brick:hasSensor ?zone .
  ?sensor a ?sclass .
}

SELECT ?node ?class ?label WHERE {
  ?node rdfs:label ?label .
  OPTIONAL { ?node a ?class }
  FILTER(CONTAINS(LCASE(str(?label)), "perimeter") || CONTAINS(LCASE(str(?label)), "ZN_2") || CONTAINS(LCASE(str(?label)), "bot"))
  LIMIT 100
}

SELECT ?node ?label WHERE {
  ?node rdfs:label ?label .
  FILTER(CONTAINS(LCASE(str(?label)), "perimeter") || CONTAINS(LCASE(str(?label)), "zn_2") || CONTAINS(LCASE(str(?label)), "bot"))
}

SELECT ?node ?class WHERE {
  ?node a ?class .
  FILTER(CONTAINS(LCASE(str(?node)), "zn_2") || CONTAINS(LCASE(str(?node)), "perimeter") || CONTAINS(LCASE(str(?node)), "bottom"))
}

SELECT ?sensor ?class ?label ?id WHERE {
